from pathlib import Path

path = Path("app/(tabs)/index.tsx")
text = path.read_text()
text = text.replace(
    'import { Alert, Animated, Easing, Platform, Pressable, ScrollView, StyleSheet, Text, useWindowDimensions, View } from "react-native";',
    'import { Alert, Animated, Easing, Modal, Platform, Pressable, ScrollView, StyleSheet, Text, useWindowDimensions, View } from "react-native";'
)
text = text.replace('import * as Sharing from "expo-sharing";\n', 'import * as Sharing from "expo-sharing";\nimport * as MediaLibrary from "expo-media-library";\n')
text = text.replace(
    'const { width, height } = useWindowDimensions(); const [manualOrientation',
    'const { width, height } = useWindowDimensions(); const [greetingPreviewVisible, setGreetingPreviewVisible] = useState(false); const greetingPreviewRef = useRef<View>(null); const [manualOrientation'
)
old_share = 'const shareGreetingCard = async () => { if (!heroCardRef.current) return; try { const uri = await captureRef(heroCardRef, { format: "png", quality: 1, result: "tmpfile" }); if (!(await Sharing.isAvailableAsync())) { Alert.alert("Berbagi belum tersedia", "Kartu ucapan sudah dibuat di perangkat ini, tetapi fitur berbagi belum tersedia pada platform sekarang."); return; } await Sharing.shareAsync(uri, { mimeType: "image/png", dialogTitle: `Bagikan kartu ucapan · ${greetingShareFormat === "square" ? "Persegi 1:1" : greetingShareFormat === "portrait" ? "Portrait 4:5" : "Story 9:16"}` }); } catch { Alert.alert("Kartu belum dibagikan", "Kartu ucapan offline belum dapat dibagikan. Coba lagi dari perangkat Anda."); } };'
new_share = 'const captureGreetingCard = async () => { if (!greetingPreviewRef.current) return null; return captureRef(greetingPreviewRef, { format: "png", quality: 1, result: "tmpfile" }); }; const saveGreetingCard = async () => { try { const uri = await captureGreetingCard(); if (!uri) return; const permission = await MediaLibrary.requestPermissionsAsync(); if (!permission.granted) { Alert.alert("Izin penyimpanan diperlukan", "Izinkan akses foto agar kartu dapat disimpan ke galeri."); return; } await MediaLibrary.saveToLibraryAsync(uri); Alert.alert("Kartu tersimpan", "Kartu ucapan sudah disimpan ke galeri."); } catch { Alert.alert("Kartu belum tersimpan", "Coba simpan kembali dari pratinjau kartu ucapan."); } }; const shareGreetingCard = async () => { try { const uri = await captureGreetingCard(); if (!uri) return; if (!(await Sharing.isAvailableAsync())) { Alert.alert("Berbagi belum tersedia", "Kartu ucapan sudah dibuat di perangkat ini, tetapi fitur berbagi belum tersedia pada platform sekarang."); return; } await Sharing.shareAsync(uri, { mimeType: "image/png", dialogTitle: `Bagikan kartu ucapan · ${greetingShareFormat === "square" ? "Persegi 1:1" : greetingShareFormat === "portrait" ? "Portrait 4:5" : "Story 9:16"}` }); } catch { Alert.alert("Kartu belum dibagikan", "Kartu ucapan offline belum dapat dibagikan. Coba lagi dari perangkat Anda."); } };'
if old_share not in text:
    raise SystemExit("share block not found")
text = text.replace(old_share, new_share)
text = text.replace('else void shareGreetingCard();', 'else setGreetingPreviewVisible(true);')
text = text.replace('heroCardMode === "greeting" && greetingShareFormatStyle, ', '')
modal = '''<Modal visible={greetingPreviewVisible} transparent animationType="fade" onRequestClose={() => setGreetingPreviewVisible(false)}><View style={styles.greetingModalBackdrop}><View style={styles.greetingModal}><View style={styles.greetingModalHeader}><Text style={[styles.greetingModalTitle, { color: colors.foreground }]}>Pratinjau kartu ucapan</Text><Pressable accessibilityLabel="Tutup pratinjau kartu" onPress={() => setGreetingPreviewVisible(false)}><MaterialIcons name="close" size={24} color={colors.foreground} /></Pressable></View><View ref={greetingPreviewRef} collapsable={false} style={[styles.greetingPreviewCard, greetingShareFormatStyle, { backgroundColor: greetingVisual.backgroundColor, borderColor: greetingVisual.accent }]}><Text style={[styles.greetingPreviewOrnament, { color: greetingVisual.accent }]}>{greetingVisual.ornament}</Text><Text style={[styles.greetingPreviewKicker, { color: greetingVisual.accent }]}>KARTU UCAPAN HARI INI</Text><Text style={[styles.greetingPreviewTitle, { color: greetingVisual.foreground }]}>{greetingTitle}</Text><Text style={[styles.greetingPreviewDetail, { color: greetingVisual.detail }]}>{greetingDetail}</Text><Text style={[styles.greetingPreviewPrompt, { color: greetingVisual.foreground }]}>{greetingPrompt}</Text></View><View style={styles.greetingModalActions}><Pressable accessibilityRole="button" onPress={() => void saveGreetingCard()} style={[styles.greetingModalButton, { borderColor: colors.border }]}><MaterialIcons name="download" size={20} color={colors.primary} /><Text style={[styles.greetingModalButtonText, { color: colors.foreground }]}>Simpan</Text></Pressable><Pressable accessibilityRole="button" onPress={() => void shareGreetingCard()} style={[styles.greetingModalButton, styles.greetingModalButtonPrimary]}><MaterialIcons name="share" size={20} color="#FFFFFF" /><Text style={styles.greetingModalButtonPrimaryText}>Bagikan</Text></Pressable></View></View></View></Modal>'''
text = text.replace('</ScrollView></ScreenContainer>;', f'</ScrollView>{modal}</ScreenContainer>;')
style_anchor = 'transaction: { alignItems: "center", flexDirection: "row", gap: 11, padding: 13 }'
styles = ', greetingModalBackdrop: { alignItems: "center", backgroundColor: "#020617AA", flex: 1, justifyContent: "center", padding: 18 }, greetingModal: { backgroundColor: "#FFFFFF", borderRadius: 22, maxWidth: 520, padding: 16, width: "100%" }, greetingModalHeader: { alignItems: "center", flexDirection: "row", justifyContent: "space-between", marginBottom: 12 }, greetingModalTitle: { fontSize: 17, fontWeight: "800" }, greetingPreviewCard: { alignSelf: "center", borderRadius: 18, borderWidth: 2, justifyContent: "center", maxHeight: 430, maxWidth: 320, minHeight: 260, overflow: "hidden", padding: 22, width: "100%" }, greetingPreviewOrnament: { fontSize: 17, fontWeight: "900", marginBottom: 14, textAlign: "center" }, greetingPreviewKicker: { fontSize: 10, fontWeight: "900", letterSpacing: 1.1, textAlign: "center" }, greetingPreviewTitle: { fontSize: 22, fontWeight: "900", lineHeight: 28, marginTop: 10, textAlign: "center" }, greetingPreviewDetail: { fontSize: 12, lineHeight: 18, marginTop: 10, textAlign: "center" }, greetingPreviewPrompt: { fontSize: 12, fontWeight: "700", lineHeight: 18, marginTop: 14, textAlign: "center" }, greetingModalActions: { flexDirection: "row", gap: 10, marginTop: 14 }, greetingModalButton: { alignItems: "center", borderRadius: 13, borderWidth: 1, flex: 1, flexDirection: "row", gap: 7, justifyContent: "center", minHeight: 46 }, greetingModalButtonPrimary: { backgroundColor: "#1677FF", borderColor: "#1677FF" }, greetingModalButtonText: { fontSize: 14, fontWeight: "800" }, greetingModalButtonPrimaryText: { color: "#FFFFFF", fontSize: 14, fontWeight: "800" }'
if style_anchor not in text:
    raise SystemExit("style anchor not found")
text = text.replace(style_anchor, style_anchor + styles)
path.write_text(text)
